def _parse_token(word, chunk="O", pnp="O", relation="O", anchor="O", 
                 format=[WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
    """ Returns a list of token tags parsed from the given <word> element.
        Tags that are not attributes in a <word> (e.g., relation) can be given as parameters.
    """
    token = []
    if WORD in format:
        token.append(word.text)
    if POS in format:
        token.append(word.get("pos"))
    if CHUNK in format:
        token.append(chunk)
    if PNP in format:
        token.append(pnp)
    if REL in format:
        token.append(relation)
    if ANCHOR in format:
        token.append(anchor)
    if LEMMA in format:
        token.append(word.get("lemma"))
    return token

