def _parse_sentence(sentence):
    """ Returns a list of tokens in a sentence.
    """
    tokens = []
    for word in sentence:
        tokens.append(_parse_token(word))
    return tokens


def _parse_snippet(snippet, format=[WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
    """ Returns a list of sentences in a snippet.
    """
    sentences = []
    for sentence in snippet:
        sentences.append(_parse_sentence(sentence, format))
    return sentences


def _parse_doc(doc, format=[WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
    """ Returns a list of snippets in a document.
    """
    snippets = []
    for snippet in doc:
        snippets.append(_parse_snippet(snippet, format))
    return snippets


def _parse_corpus(corpus, format=[WORD, POS, CHUNK, PNP, REL, ANCHOR, LEMMA]):
    """ Returns a list of documents in a corpus.
    """
    docs = []
    for doc in corpus:
        docs.append(_parse_doc(doc, format))
    return docs


